import { createClient, RedisClientType } from 'redis';
import debug from 'debug';

export const log = debug('umami:redis-client');

export const DELETED = '__DELETED__';

const logError = (err: unknown) => log(err);

export interface UmamiRedisClientOptions {
  url: string;
}

export class UmamiRedisClient {
  url: string;
  client: RedisClientType;
  isConnected: boolean;

  constructor({ url }: UmamiRedisClientOptions) {
    const client = createClient({ url }).on('error', logError);

    this.url = url;
    this.client = client as RedisClientType;
    this.isConnected = false;
  }

  async connect() {
    if (!this.isConnected) {
      this.isConnected = true;

      await this.client.connect();

      log('Redis connected');
    }
  }

  async get(key: string) {
    await this.connect();

    const data = await this.client.get(key);

    try {
      return JSON.parse(data as string);
    } catch {
      return null;
    }
  }

  async set(key: string, value: any) {
    await this.connect();

    return this.client.set(key, JSON.stringify(value));
  }

  async del(key: string) {
    await this.connect();

    return this.client.del(key);
  }

  async incr(key: string) {
    await this.connect();

    return this.client.incr(key);
  }

  async expire(key: string, seconds: number) {
    await this.connect();

    return this.client.expire(key, seconds);
  }

  async rateLimit(key: string, limit: number, seconds: number): Promise<boolean> {
    await this.connect();

    const res = await this.client.incr(key);

    if (res === 1) {
      await this.client.expire(key, seconds);
    }

    return res >= limit;
  }

  async fetch(key: string, query: () => Promise<any>, time: number = 0) {
    const result = await this.get(key);

    if (result === DELETED) {
      return null;
    }

    if (!result && query) {
      return await Promise.resolve(query()).then(async data => {
        if (data) {
          await this.store(key, data, time);
        }

        return data;
      });
    }

    return result;
  }

  async store(key: string, data: any, time: number = 0) {
    const result = this.set(key, data);

    if (time > 0) {
      await this.expire(key, time);
    }

    return result;
  }

  async remove(key: string, soft = false) {
    return soft ? this.set(key, DELETED) : this.del(key);
  }
}

export default UmamiRedisClient;

import resolve from '@rollup/plugin-node-resolve';
import commonjs from '@rollup/plugin-commonjs';
import esbuild from 'rollup-plugin-esbuild';
import dts from 'rollup-plugin-dts';

const external = ['redis', 'debug'];

export default [
  {
    input: 'src/index.ts',
    output: [
      {
        file: 'dist/index.js',
        format: 'cjs',
        exports: 'named',
      },
    ],
    plugins: [resolve(), commonjs(), esbuild()],
    external,
  },
  {
    input: 'src/index.ts',
    output: [
      {
        file: 'dist/index.d.ts',
        format: 'es',
      },
    ],
    plugins: [dts()],
    external,
  },
];

module.exports = {
  verbose: true,
  testEnvironment: 'jsdom',
  moduleFileExtensions: ['ts', 'tsx', 'js', 'jsx', 'json'],
  moduleNameMapper: {
    '\\.(css|less|jpg|png|svg)$': '<rootDir>/test/mocks/emptyModule.js',
    '^(components|assets|hooks|styles)(.*)': '<rootDir>/src/$1/$2',
    '^(icons)': '<rootDir>/src/$1',
  },
};

{
  "env": {
    "browser": true,
    "commonjs": true,
    "es6": true,
    "node": true,
    "jest": true
  },

  "parser": "@typescript-eslint/parser",
  "parserOptions": {
    "ecmaVersion": 9
  },
  "globals": {
    "JSX": true
  },
  "extends": [
    "plugin:@typescript-eslint/recommended",
    "eslint:recommended",
    "prettier"
  ],
  "plugins": [
    "@typescript-eslint",
    "prettier"
  ],
  "rules": {
    "linebreak-style": ["error", "unix"],
    "max-len": [
      "error",
      {
        "code": 100,
        "ignoreComments": true
      }
    ],
    "import/no-unresolved": "off",
    "no-unused-vars": "off",
    "@typescript-eslint/no-explicit-any": "off",
    "@typescript-eslint/no-unused-vars": ["error"],
    "@typescript-eslint/no-var-requires": "off",
    "@typescript-eslint/no-empty-function": "off"
  }
}
